"""Local offline object-store adapter for Stage 3; later replace with private S3."""
from pathlib import Path
from uuid import uuid4
import hashlib
import os
import tempfile
from fastapi import HTTPException, UploadFile, status


class LocalStorage:
    def __init__(self, root: Path):
        self.root = root.resolve()
        self.root.mkdir(parents=True, exist_ok=True)

    def path(self, key: str) -> Path:
        # Keys are generated by the application, never filenames from user requests.
        if "/" in key or "\\" in key or key.startswith("."):
            raise ValueError("Unsafe storage key")
        return self.root / key

    def save_pdf(self, upload: UploadFile, max_bytes: int) -> tuple[str, int, str]:
        key = f"{uuid4().hex}.pdf"
        fpath = self.path(key)
        digest = hashlib.sha256()
        length = 0
        tmp = None
        try:
            with tempfile.NamedTemporaryFile(dir=self.root, prefix="pending-", delete=False) as dest:
                tmp = Path(dest.name)
                header = upload.file.read(5)
                if header != b"%PDF-":
                    raise HTTPException(status.HTTP_415_UNSUPPORTED_MEDIA_TYPE, "Valid PDF required")
                dest.write(header)
                digest.update(header)
                length += len(header)
                while block := upload.file.read(65536):
                    length += len(block)
                    if length > max_bytes:
                        raise HTTPException(status.HTTP_413_CONTENT_TOO_LARGE, "PDF is too large")
                    dest.write(block)
                    digest.update(block)
            os.replace(tmp, fpath)
            os.chmod(fpath, 0o600)
            return key, length, digest.hexdigest()
        finally:
            if tmp:
                tmp.unlink(missing_ok=True)

    def save_text(self, text: str) -> str:
        key = f"{uuid4().hex}.txt"
        target = self.path(key)
        tmp = None
        try:
            with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=self.root,
                                             prefix="pending-", delete=False) as dest:
                tmp = Path(dest.name)
                dest.write(text)
            os.replace(tmp, target)
            os.chmod(target, 0o600)
            return key
        finally:
            if tmp:
                tmp.unlink(missing_ok=True)

    def delete(self, key: str):
        self.path(key).unlink(missing_ok=True)
